contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will: 1) fund the contract for this test sender via Put, 2) read balances, 3) call Collect (maybe revert),
    // 4) assert that if Collect succeeded then Acc[msg.sender].balance decreased by exactly _am and address(c).balance decreased by >= _am.
    // We cannot directly observe Acc mapping except via its autogenerated getter Acc(address) returns (uint unlockTime, uint balance).

    // single public test function
    function run(uint putUnlock, uint putAmount, uint collectAmount) public payable {
        // ensure this test contract has enough ETH to send the Put value
        require(address(this).balance >= putAmount, "insufficient balance for Put");

        // 1) call Put to deposit putAmount for this test contract's address into c
        c.Put{value: putAmount}(putUnlock);

        // read the holder info for this contract (which is msg.sender from c's perspective)
        (uint beforeUnlock, uint beforeBal) = c.Acc(address(this));
        uint beforeContractBal = address(c).balance;

        // 2) attempt Collect and record whether it reverted
        bool reverted;
        try c.Collect{value: 0}(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read after-state
        (uint afterUnlock, uint afterBal) = c.Acc(address(this));
        uint afterContractBal = address(c).balance;

        // If Collect succeeded (did not revert), then:
        // - beforeBal must have been >= collectAmount (Collect checks that), and block.timestamp > beforeUnlock (or revert)
        // - afterBal must equal beforeBal - collectAmount
        // - contract's ETH balance must have decreased by at least collectAmount (it may decrease exactly by collectAmount)
        // We cannot reference block.timestamp here, so we assert only observable relations.

        assert(reverted || (beforeBal >= collectAmount
               && afterBal == beforeBal - collectAmount
               && beforeContractBal >= afterContractBal
               && beforeContractBal - afterContractBal >= collectAmount));
    }

    // allow receiving ETH so the test harness can fund this contract
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We test that a successful Put{value: amt}(unlock) increases both the stored balance
    // for this contract and the contract's Ether balance by exactly amt.
    // Inputs: unlock time and deposit amount. The function is payable so the harness can fund this contract.
    function run(uint putUnlock, uint putAmount) public payable {
        // ensure test contract has enough ETH to send
        require(address(this).balance >= putAmount, "insufficient balance for Put");

        // read before-values
        (uint beforeUnlock, uint beforeBal) = c.Acc(address(this));
        uint beforeContractBal = address(c).balance;

        // perform Put and record whether it reverted
        bool reverted;
        try c.Put{value: putAmount}(putUnlock) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read after-values
        (uint afterUnlock, uint afterBal) = c.Acc(address(this));
        uint afterContractBal = address(c).balance;

        // If Put succeeded then:
        // - the stored balance for this address increases by exactly putAmount
        // - the contract's Ether balance increases by exactly putAmount
        // Also, when Put succeeds, afterUnlock should be set to max(putUnlock, block.timestamp).
        // We cannot reference block.timestamp in the assertion, so we assert that if not reverted,
        // then balances changed exactly by putAmount and afterBal >= beforeBal.
        assert(reverted || (
            afterBal == beforeBal + putAmount
            && afterContractBal == beforeContractBal + putAmount
            && afterBal >= beforeBal
        ));
    }

    // allow receiving ETH so the test harness can fund this contract
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Test: after a successful Collect{value:0}(_am) called by this test contract,
    // the on-chain stored balance Acc[this].balance decreases by exactly _am,
    // and address(c).balance decreases by at least _am.
    // We ensure preconditions so Collect can succeed: deposit >= MinSum and set unlockTime in past.
    function run(uint depositUnlockFuture, uint depositAmount, uint collectAmount) public payable {
        // need ETH to fund the initial Put
        require(address(this).balance >= depositAmount, "insufficient balance for Put");

        // make an initial Put to create a positive balance for this contract
        // Call Put with an unlock time in the past (0) so that after block.timestamp it is <= now.
        // However Put sets unlockTime = max(_unlockTime, block.timestamp). To allow Collect to succeed
        // we will first call Put with unlock time 0, then manually set a later unlock by calling Put again
        // with 0 is enough because it sets unlock to block.timestamp; Collect requires block.timestamp > unlockTime,
        // so we need unlockTime in the past. To achieve that deterministically in one tx, call Put twice:
        // first to deposit and set unlock to now, then call Put with unlock 0 via fallback by sending 0 value to invoke fallback -> Put(0)
        // But fallback also calls Put(0) and will set unlock to now again. Therefore to ensure unlockTime < block.timestamp for Collect,
        // instead we rely on passing a large depositUnlockFuture and then make a second Put with 0 and 0 value is not helpful.
        // Simpler approach: call Put with unlock = 0 and then assert only when Collect succeeds; Collect can only succeed when block.timestamp > unlockTime.
        // So we make a deposit and then attempt Collect; if Collect succeeded, we assert the balance changes accordingly.

        // Perform initial Put
        c.Put{value: depositAmount}(depositUnlockFuture);

        // read before-values
        (uint beforeUnlock, uint beforeBal) = c.Acc(address(this));
        uint beforeContractBal = address(c).balance;

        // attempt Collect; capture whether it reverted
        bool reverted;
        try c.Collect{value: 0}(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read after-values
        (uint afterUnlock, uint afterBal) = c.Acc(address(this));
        uint afterContractBal = address(c).balance;

        // If Collect succeeded then stored balance decreased by exactly collectAmount and contract balance decreased by at least collectAmount.
        assert(reverted || (beforeBal >= collectAmount && afterBal + collectAmount == beforeBal && beforeContractBal >= afterContractBal && beforeContractBal - afterContractBal >= collectAmount));
    }

    receive() external payable {}
}

