    // We take params: an initial deposit `depositAmt`, an `_unlockTime` to set on Put,
    // and a withdrawal amount `_am` to attempt to Collect.
    function run(uint depositAmt, uint _unlockTime, uint _am) public payable {
        // Ensure this test contract can send the desired deposit amount
        require(address(this).balance >= depositAmt);

        // Initial observable state
        (uint beforeUnlock, uint beforeBalance) = c.Acc(address(this));
        uint cBalanceBefore = address(c).balance;

        // Make a deposit to set up funds and unlockTime (may revert)
        bool depositReverted;
        try c.Put{value: depositAmt}(_unlockTime) {
            depositReverted = false;
        } catch {
            depositReverted = true;
        }

        // After deposit attempt, read state
        (uint midUnlock, uint midBalance) = c.Acc(address(this));
        uint cBalanceMid = address(c).balance;

        // Ensure time is past unlock so Collect may succeed if balances suffice.
        // We cannot advance block.timestamp; instead choose an _unlockTime that is <= current block.timestamp
        // to allow Collect to potentially proceed. Require that in inputs so the rule is meaningful.
        require(_unlockTime <= block.timestamp);

        // Attempt Collect of `_am` and record whether it reverted
        bool collectReverted;
        try c.Collect{value: 0}(_am) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // Read after-values
        (uint afterUnlock, uint afterBalance) = c.Acc(address(this));
        uint cBalanceAfter = address(c).balance;

        // The property:
        // - If Collect succeeded: recorded balance decreased by exactly _am and contract balance decreased by exactly _am.
        // - If Collect reverted: neither the recorded balance nor the contract balance increased (they may stay same or decrease due to failed deposit earlier), but specifically they are not greater than their mid-values.
        assert(
            collectReverted
            ? (afterBalance <= midBalance && cBalanceAfter <= cBalanceMid)
            : (midBalance >= _am && afterBalance + _am == midBalance && cBalanceMid >= _am && cBalanceAfter + _am == cBalanceMid)
        );
    }

    // Allow receiving Ether
    receive() external payable {}
}

