contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We'll try arbitrary withdraw amount and unlockTime and deposit amount.
    // The test will: deposit funds via Put, optionally set unlockTime, then attempt Collect(_am).
    // It asserts: if Collect did not revert, Acc(msg.sender).balance decreased by _am and contract balance decreased by _am.

    function run(uint unlockTime, uint depositAmount, uint withdrawAmount) public payable {
        require(address(this).balance >= depositAmount, "insufficient test balance");

        // Initial reading of contract balance and holder balance for this test contract (InvMutTest is msg.sender to c)
        uint beforeContractBal = address(c).balance;
        // Call Put to deposit depositAmount and set unlockTime
        c.Put{value: depositAmount}(unlockTime);

        // Read holder balance after deposit
        (uint accUnlockTime, uint accBalance) = c.Acc(address(this));

        // Ensure conditions that would allow Collect to proceed: must have accBalance >= MinSum and accBalance >= withdrawAmount and block.timestamp > acc.unlockTime
        // We cannot change block.timestamp, so to allow Collect we choose withdrawAmount <= accBalance and depositAmount ensures accBalance >= withdrawAmount.
        // To avoid making the test depend on block.timestamp, we attempt Collect and record whether it reverted.
        bool reverted;
        // Attempt Collect; must be top-level statement when it changes c's state
        try c.Collect(withdrawAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterContractBal = address(c).balance;
        (uint accUnlockTime2, uint accBalance2) = c.Acc(address(this));

        // If the call succeeded (did not revert), then the recorded balance decreased by exactly withdrawAmount
        // and the contract's balance decreased by exactly withdrawAmount.
        assert(reverted || (accBalance2 + withdrawAmount == accBalance && beforeContractBal + depositAmount - afterContractBal == withdrawAmount));
    }

    // receive to accept Ether refunds if any
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will: deposit some amount via Put, then attempt Collect(amount).
    // We assert: if Collect did not revert then the public getter Acc(address(this)).balance after the call
    // equals the value read (we read via the public getter) and is <= the balance before Collect.
    // This avoids relying on observed Ether transfers (call success may happen but send might fail),
    // and focuses on the contract's recorded holder balance monotonicity on successful Collect.

    function run(uint unlockTime, uint depositAmount, uint withdrawAmount) public payable {
        require(address(this).balance >= depositAmount, "insufficient test balance");

        // Record contract balance before any interaction
        uint beforeContractBal = address(c).balance;

        // Deposit depositAmount and set unlockTime
        c.Put{value: depositAmount}(unlockTime);

        // Read holder info after deposit
        (uint accUnlockBefore, uint accBalanceBefore) = c.Acc(address(this));

        bool reverted;
        // Attempt Collect; top-level changing call
        try c.Collect(withdrawAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read holder info after Collect attempt
        (uint accUnlockAfter, uint accBalanceAfter) = c.Acc(address(this));

        // General rule: if Collect did not revert then the recorded holder balance after the call
        // must be <= the recorded holder balance before the call (monotonic decrease or same),
        // and the getter returned value accBalanceAfter is the authoritative recorded balance.
        // We express this as: reverted || accBalanceAfter <= accBalanceBefore
        assert(reverted || accBalanceAfter <= accBalanceBefore);
    }

    receive() external payable {}
}
